insert into document_sections (id, version_id, position, heading, page, body) values ('090163aa-1595-4566-a601-104cc4d52e4a', 'c3d1d032-a513-4538-a5b7-03bc8b73ec98', 0, 'Overview', 2, 'A summer creator programme for Game Pass built around five Northlight creators on YouTube and Twitch over an eight-week flight from late June.');
insert into document_sections (id, version_id, position, heading, page, body) values ('cefd2dac-9958-43c8-a584-981a8d4b7d80', 'c3d1d032-a513-4538-a5b7-03bc8b73ec98', 1, 'Creator lineup', 5, 'Five creators: two variety streamers, two shooter specialists and one cozy-games creator, with combined reach of 18M.');
insert into document_sections (id, version_id, position, heading, page, body) values ('4e016ed0-5b1c-4fb4-a9e1-ad25bd51709d', 'c3d1d032-a513-4538-a5b7-03bc8b73ec98', 2, 'Investment', 12, 'Total investment $120,000 covering creator fees, production and $20,000 paid amplification.');
